def _label_basis(z):
    paired_products = z[:, 0] * z[:, 2] + z[:, 1] * z[:, 3]
    return np.column_stack((_affine(z), paired_products))

def _trajectory(design, observed, design_test, times):
    from scipy.optimize import least_squares
    affine_coeff = _fit(design, observed)

    def time_basis(log_rates):
        return -np.expm1(-np.exp(log_rates)[:, None] * times)

    def profile(log_rates):
        basis = time_basis(log_rates)
        amplitudes = _fit(basis.T, affine_coeff.T).T
        return amplitudes @ basis

    def residual(log_rates):
        return (design @ (affine_coeff - profile(log_rates))).ravel()
    rates = least_squares(residual, np.log([0.4, 1.8]), bounds=(-4, 3)).x
    return design_test @ profile(rates)

def _operator(panel):
    from scipy.optimize import least_squares
    (u, v) = (panel['u'], panel['v'])

    def design(x, q):
        (k, a) = np.exp(q)
        return _affine(x * (1 - a * np.exp(-k * x ** 2)))

    def residual(q):
        d = design(u, q)
        return (d @ _fit(d, v) - v).ravel()
    q = least_squares(residual, np.log([0.7, 1.06]), bounds=(-4, 2)).x
    weights = _fit(design(u, q), v)
    return lambda x: design(x, q) @ weights

def _state_readout(design, observed, test_design, times):
    from scipy.optimize import least_squares
    coeff = _fit(design, observed)

    def projected(log_rates):
        basis = -np.expm1(-np.exp(log_rates)[:, None] * times)
        return _fit(basis.T, coeff.T).T @ basis

    def residual(log_rates):
        return (design @ (projected(log_rates) - coeff)).ravel()
    result = least_squares(residual, np.log([0.4, 1.8]), bounds=(-4, 3))
    return test_design @ projected(result.x)
